const parseDryRun = (v) => v === true || v === 'true' || v === 1 || v === '1';

let body = $json.body ?? $json;
if (typeof body === 'string') {
  try {
    body = JSON.parse(body);
  } catch {
    body = {};
  }
}
if (!body || typeof body !== 'object') body = {};

const daysInput = body.days;
const dryRunRaw = body.dryRun ?? $json.dryRun ?? $json.query?.dryRun;
const dryRun = parseDryRun(dryRunRaw);
const startedAtISO = new Date().toISOString();

if (daysInput === undefined || daysInput === null || daysInput === '') {
  return [{ json: { ok: true, days: 30, dryRun, startedAtISO } }];
}

const d = Number(daysInput);
if (!Number.isFinite(d) || Math.trunc(d) < 1) {
  return [{
    json: {
      ok: false,
      reason: 'INVALID_DAYS',
      message: 'days must be a positive integer',
      days: 30,
      dryRun,
      startedAtISO
    }
  }];
}

return [{ json: { ok: true, days: Math.min(90, Math.trunc(d)), dryRun, startedAtISO } }];

const req = $('Parse_Request').first().json || {};
const days = Number(req.days || 30);
const dryRun = req.dryRun === true;
const startedAtISO = req.startedAtISO || new Date().toISOString();
const inputRows = $input.all().map((i) => i.json || {});
const rows = inputRows.filter((r) => {
  if (!r || typeof r !== 'object') return false;
  return Object.values(r).some((v) => {
    if (v === null || v === undefined) return false;
    if (typeof v === 'string') return v.trim() !== '';
    return true;
  });
});

if (!rows.length) {
  return [{
    json: {
      ok: false,
      reason: 'NO_RAW_DATA',
      message: 'raw_events is empty',
      days,
      dryRun,
      startedAtISO,
      summary: {
        rawRowsRead: 0,
        windowRows: 0,
        uniqueVideos: 0,
        dailyRows: 0,
        keywordRows: 0,
        snippetRows: 0,
        rejectedCount: 0
      }
    }
  }];
}

const toNumOrNull = (v) => {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
};

const toDateString = (v) => {
  if (typeof v === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(v)) return v;
  return null;
};

const toIso = (v) => {
  if (!v) return null;
  const d = new Date(v);
  return Number.isNaN(d.getTime()) ? null : d.toISOString();
};

const now = new Date();
const todayKST = now.toLocaleDateString('en-CA', { timeZone: 'Asia/Seoul' });
const start = new Date(now.getTime() - (Math.max(1, days) - 1) * 86400000);
const startKST = start.toLocaleDateString('en-CA', { timeZone: 'Asia/Seoul' });

const normalized = rows.map((r) => {
  const collectedAtISO = toIso(r.collectedAtISO);
  const createTimeISO = toIso(r.createTimeISO);
  const createDateKST = toDateString(r.createDateKST);

  return {
    collectedAtISO,
    collectedDateKST: toDateString(r.collectedDateKST),
    createTimeISO,
    createDateKST,
    bucket: r.bucket || null,
    keyword: r.keyword || null,
    query: r.query || null,
    proxyCountryCode: r.proxyCountryCode || null,
    id: r.id || null,
    text: r.text || null,
    textLanguage: r.textLanguage || null,
    videoUrl: r.videoUrl || null,
    authorName: r.authorName || null,
    authorNickName: r.authorNickName || null,
    authorProfileUrl: r.authorProfileUrl || null,
    authorFollowers: toNumOrNull(r.authorFollowers),
    playCount: toNumOrNull(r.playCount),
    diggCount: toNumOrNull(r.diggCount),
    shareCount: toNumOrNull(r.shareCount),
    commentCount: toNumOrNull(r.commentCount),
    inLookback: r.inLookback === true || r.inLookback === 'TRUE' || r.inLookback === 'true'
  };
});

const filtered = normalized.filter((r) => r.id && r.createDateKST && r.createDateKST >= startKST && r.createDateKST <= todayKST);

const dedupe = new Map();
for (const row of filtered) {
  const prev = dedupe.get(row.id);
  if (!prev) {
    dedupe.set(row.id, row);
    continue;
  }
  const prevTs = new Date(prev.collectedAtISO || 0).getTime();
  const currTs = new Date(row.collectedAtISO || 0).getTime();
  if (currTs >= prevTs) dedupe.set(row.id, row);
}

const dedupedRows = Array.from(dedupe.values());
const warning = dedupedRows.length === 0 ? 'NO_ROWS_AFTER_DEDUPE' : null;

return [{
  json: {
    ok: dedupedRows.length > 0,
    reason: dedupedRows.length > 0 ? null : 'NO_DEDUPED_ROWS',
    warning,
    days,
    dryRun,
    startedAtISO,
    windowStartKST: startKST,
    windowEndKST: todayKST,
    totalRawRows: rows.length,
    filteredRows: filtered.length,
    dedupedRows,
    summary: {
      rawRowsRead: rows.length,
      windowRows: filtered.length,
      uniqueVideos: dedupedRows.length,
      dailyRows: 0,
      keywordRows: 0,
      snippetRows: 0,
      rejectedCount: Math.max(0, rows.length - filtered.length)
    }
  }
}];

const payload = $json || {};
const rows = Array.isArray(payload.dedupedRows) ? payload.dedupedRows : [];
const getEnvInt = (key, fallback) => { const n = Number.parseInt($env[key] ?? '', 10); return Number.isFinite(n) ? n : fallback; };
const topN = Math.max(1, getEnvInt('TOP_SNIPPETS_N', 5));
const creatorTopN = Math.max(1, getEnvInt('CREATORS_PREVIEW_TOP_N', 20));
const creatorMaxRows = Math.max(1, getEnvInt('CREATORS_MAX_ROWS', 500));

const numStat = () => ({ sum: 0, count: 0 });
const addNum = (stat, val) => {
  if (val === null || val === undefined || val === '') return;
  const n = Number(val);
  if (!Number.isFinite(n)) return;
  stat.sum += n;
  stat.count += 1;
};
const statValue = (stat) => (stat.count > 0 ? stat.sum : null);
const statAvg = (stat, baseCount) => (baseCount > 0 && stat.count > 0 ? +(stat.sum / baseCount).toFixed(2) : null);

const byDaily = new Map();
for (const r of rows) {
  const key = `${r.createDateKST}||${r.bucket || ''}||${r.keyword || ''}`;
  if (!byDaily.has(key)) {
    byDaily.set(key, {
      date_kst: r.createDateKST,
      bucket: r.bucket || null,
      keyword: r.keyword || null,
      videos_count: 0,
      play: numStat(), digg: numStat(), share: numStat(), comment: numStat()
    });
  }
  const cur = byDaily.get(key);
  cur.videos_count += 1;
  addNum(cur.play, r.playCount);
  addNum(cur.digg, r.diggCount);
  addNum(cur.share, r.shareCount);
  addNum(cur.comment, r.commentCount);
}

const dailyRows = Array.from(byDaily.values())
  .map((r) => ({
    date_kst: r.date_kst,
    bucket: r.bucket,
    keyword: r.keyword,
    videos_count: r.videos_count,
    play_sum: statValue(r.play),
    digg_sum: statValue(r.digg),
    share_sum: statValue(r.share),
    comment_sum: statValue(r.comment),
    play_avg: statAvg(r.play, r.videos_count),
    digg_avg: statAvg(r.digg, r.videos_count),
    share_avg: statAvg(r.share, r.videos_count),
    comment_avg: statAvg(r.comment, r.videos_count)
  }))
  .sort((a, b) => a.date_kst.localeCompare(b.date_kst) || (a.bucket || '').localeCompare(b.bucket || '') || (a.keyword || '').localeCompare(b.keyword || ''));

const byKeyword = new Map();
for (const r of rows) {
  const key = `${r.bucket || ''}||${r.keyword || ''}`;
  if (!byKeyword.has(key)) {
    byKeyword.set(key, {
      bucket: r.bucket || null,
      keyword: r.keyword || null,
      videos_count: 0,
      play: numStat(), digg: numStat(), share: numStat(), comment: numStat()
    });
  }
  const cur = byKeyword.get(key);
  cur.videos_count += 1;
  addNum(cur.play, r.playCount);
  addNum(cur.digg, r.diggCount);
  addNum(cur.share, r.shareCount);
  addNum(cur.comment, r.commentCount);
}

const keywordRows = Array.from(byKeyword.values())
  .map((r) => ({
    bucket: r.bucket,
    keyword: r.keyword,
    videos_count: r.videos_count,
    play_sum: statValue(r.play),
    digg_sum: statValue(r.digg),
    share_sum: statValue(r.share),
    comment_sum: statValue(r.comment),
    play_per_video: statAvg(r.play, r.videos_count),
    digg_per_video: statAvg(r.digg, r.videos_count),
    share_per_video: statAvg(r.share, r.videos_count),
    comment_per_video: statAvg(r.comment, r.videos_count)
  }))
  .sort((a, b) => (a.bucket || '').localeCompare(b.bucket || '') || (a.keyword || '').localeCompare(b.keyword || ''));

const byBucketKeyword = new Map();
for (const r of rows) {
  const key = `${r.bucket || ''}||${r.keyword || ''}`;
  if (!byBucketKeyword.has(key)) byBucketKeyword.set(key, []);
  byBucketKeyword.get(key).push(r);
}

const snippetRows = [];
for (const arr of byBucketKeyword.values()) {
  const sorted = [...arr].sort((a, b) => {
    const ap = Number.isFinite(Number(a.playCount)) ? Number(a.playCount) : -1;
    const bp = Number.isFinite(Number(b.playCount)) ? Number(b.playCount) : -1;
    return bp - ap;
  }).slice(0, topN);

  for (const r of sorted) {
    snippetRows.push({
      bucket: r.bucket,
      keyword: r.keyword,
      id: r.id,
      createDateKST: r.createDateKST,
      createTimeISO: r.createTimeISO,
      playCount: r.playCount,
      diggCount: r.diggCount,
      shareCount: r.shareCount,
      commentCount: r.commentCount,
      text: r.text,
      videoUrl: r.videoUrl,
      authorNickName: r.authorNickName,
      authorFollowers: r.authorFollowers
    });
  }
}

const rejected_with_reason = [];
const creatorsMap = new Map();

const normalizeHandleFromProfile = (url) => {
  if (!url || typeof url !== 'string') return null;
  const m = url.match(/@([A-Za-z0-9._]+)/);
  if (m?.[1]) return m[1].toLowerCase();
  const parts = url.split('/').filter(Boolean);
  if (!parts.length) return null;
  const last = parts[parts.length - 1];
  if (!last || last.startsWith('http')) return null;
  return last.toLowerCase();
};

for (const r of rows) {
  const profile = (r.authorProfileUrl || '').trim() || null;
  const handle = normalizeHandleFromProfile(profile) || (r.authorNickName ? String(r.authorNickName).trim().toLowerCase() : null);
  if (!profile && !handle) {
    rejected_with_reason.push({
      reason: 'MISSING_AUTHOR_ID',
      id: r.id || null,
      keyword: r.keyword || null,
      bucket: r.bucket || null,
      authorProfileUrl: r.authorProfileUrl || null,
      authorNickName: r.authorNickName || null
    });
    continue;
  }

  const creatorKey = profile || `handle:${handle}`;
  if (!creatorsMap.has(creatorKey)) {
    creatorsMap.set(creatorKey, {
      authorHandle: handle,
      authorName: r.authorName || null,
      authorNickName: r.authorNickName || null,
      authorProfileUrl: profile,
      authorFollowers: (r.authorFollowers === null || r.authorFollowers === undefined || r.authorFollowers === '') ? null : Number(r.authorFollowers),
      postsCount: 0,
      play: numStat(),
      topPlay: null,
      topPostUrl: null,
      keywordsSeenSet: new Set()
    });
  }

  const cur = creatorsMap.get(creatorKey);
  cur.postsCount += 1;
  addNum(cur.play, r.playCount);

  if (r.keyword) cur.keywordsSeenSet.add(String(r.keyword));
  if (!cur.authorName && r.authorName) cur.authorName = r.authorName;
  if (!cur.authorNickName && r.authorNickName) cur.authorNickName = r.authorNickName;
  if (!cur.authorProfileUrl && profile) cur.authorProfileUrl = profile;
  if (!cur.authorHandle && handle) cur.authorHandle = handle;

  const followersN = (r.authorFollowers === null || r.authorFollowers === undefined || r.authorFollowers === '') ? null : Number(r.authorFollowers);
  if (Number.isFinite(followersN)) {
    if (cur.authorFollowers === null || cur.authorFollowers === undefined || cur.authorFollowers === '' || !Number.isFinite(Number(cur.authorFollowers)) || followersN > Number(cur.authorFollowers)) {
      cur.authorFollowers = followersN;
    }
  }

  const playN = Number.isFinite(Number(r.playCount)) ? Number(r.playCount) : null;
  if (playN !== null && (cur.topPlay === null || playN > cur.topPlay)) {
    cur.topPlay = playN;
    cur.topPostUrl = r.videoUrl || null;
  }
}

const creatorsRows = Array.from(creatorsMap.values()).map((c) => {
  const totalPlays = statValue(c.play);
  const avgPlays = c.postsCount > 0 && c.play.count > 0 ? +(c.play.sum / c.postsCount).toFixed(2) : null;
  return {
    authorHandle: c.authorHandle || null,
    authorName: c.authorName || null,
    authorNickName: c.authorNickName || null,
    authorProfileUrl: c.authorProfileUrl || null,
    authorFollowers: Number.isFinite(Number(c.authorFollowers)) ? Number(c.authorFollowers) : null,
    postsCount: c.postsCount,
    totalPlays,
    avgPlays,
    topPostUrl: c.topPostUrl || null,
    keywordsSeen: Array.from(c.keywordsSeenSet).sort()
  };
}).sort((a, b) => {
  const ap = Number.isFinite(Number(a.totalPlays)) ? Number(a.totalPlays) : -1;
  const bp = Number.isFinite(Number(b.totalPlays)) ? Number(b.totalPlays) : -1;
  if (bp !== ap) return bp - ap;
  const af = Number.isFinite(Number(a.authorFollowers)) ? Number(a.authorFollowers) : -1;
  const bf = Number.isFinite(Number(b.authorFollowers)) ? Number(b.authorFollowers) : -1;
  if (bf !== af) return bf - af;
  return (a.authorHandle || '').localeCompare(b.authorHandle || '');
});

const creatorsRowsCapped = creatorsRows.slice(0, creatorMaxRows);
const creatorsPreviewTopN = creatorsRowsCapped.slice(0, creatorTopN);
const creatorSummary = {
  creatorsTotal: creatorsRows.length,
  rejectedCount: rejected_with_reason.length,
  previewCount: creatorsPreviewTopN.length,
  groupingKey: 'authorProfileUrl_or_authorHandle'
};

const dailyHeader = ['date_kst','bucket','keyword','videos_count','play_sum','digg_sum','share_sum','comment_sum','play_avg','digg_avg','share_avg','comment_avg'];
const keywordHeader = ['bucket','keyword','videos_count','play_sum','digg_sum','share_sum','comment_sum','play_per_video','digg_per_video','share_per_video','comment_per_video'];
const snippetHeader = ['bucket','keyword','id','createDateKST','createTimeISO','playCount','diggCount','shareCount','commentCount','text','videoUrl','authorNickName','authorFollowers'];

const summary = {
  rawRowsRead: Number(payload.totalRawRows || 0),
  windowRows: Number(payload.filteredRows || 0),
  uniqueVideos: rows.length,
  dailyRows: dailyRows.length,
  keywordRows: keywordRows.length,
  snippetRows: snippetRows.length,
  rejectedCount: Math.max(0, Number(payload.totalRawRows || 0) - Number(payload.filteredRows || 0))
};

return [{
  json: {
    ok: true,
    dryRun: payload.dryRun === true,
    days: payload.days,
    startedAtISO: payload.startedAtISO || new Date().toISOString(),
    windowStartKST: payload.windowStartKST,
    windowEndKST: payload.windowEndKST,
    totalRawRows: payload.totalRawRows,
    filteredRows: payload.filteredRows,
    dedupedRows: rows.length,
    warning: payload.warning || null,
    summary,
    creatorSummary,
    creatorsRowsFull: creatorsRowsCapped,
    creatorsPreviewTopN,
    creatorsRejectedWithReason: rejected_with_reason,
    sampleDedupedTop1: rows[0] ?? null,
    top5MappedRows: rows.slice(0, 5),
    dailyPreviewTop3: dailyRows.slice(0, 3),
    keywordPreviewTop3: keywordRows.slice(0, 3),
    snippetsPreviewTop3: snippetRows.slice(0, 3),
    dailyMatrix: [dailyHeader, ...dailyRows.map((r) => dailyHeader.map((h) => r[h] ?? null))],
    keywordMatrix: [keywordHeader, ...keywordRows.map((r) => keywordHeader.map((h) => r[h] ?? null))],
    snippetMatrix: [snippetHeader, ...snippetRows.map((r) => snippetHeader.map((h) => r[h] ?? null))]
  }
}];

const BUILD_TAG = 'aggregator-sp2-2026-02-26-dryrun-fixed';
const fallback = $json || {};

const serializeError = (e) => {
  if (!e) return null;
  if (typeof e === 'string') return { name: 'Error', message: e };
  return {
    name: e.name ? String(e.name) : 'Error',
    message: e.message ? String(e.message) : String(e),
    stack: e.stack ? String(e.stack) : undefined
  };
};

const isEmptyObject = (v) => !v || typeof v !== 'object' || Object.keys(v).length === 0;

try {
  let source = fallback;
  if (isEmptyObject(source) || (source.ok === undefined && source.summary === undefined && source.reason === undefined)) {
    try {
      const built = $('Build_Aggregates').first().json;
      if (built && typeof built === 'object') source = built;
    } catch {
      // Keep fallback source
    }
  }

  const startedAtISO = source.startedAtISO || new Date().toISOString();
  const finishedAtISO = new Date().toISOString();
  const durationMs = Math.max(0, new Date(finishedAtISO).getTime() - new Date(startedAtISO).getTime());

  const defaultWouldWriteRanges = {
    clearDaily: `${$env.GSHEET_DAILY_TAB || 'daily_metrics'}!A1:Z`,
    writeDaily: `${$env.GSHEET_DAILY_TAB || 'daily_metrics'}!A1:Z`,
    clearKeyword: `${$env.GSHEET_KEYWORD_TAB || 'keyword_totals'}!A1:Z`,
    writeKeyword: `${$env.GSHEET_KEYWORD_TAB || 'keyword_totals'}!A1:Z`,
    clearSnippets: `${$env.GSHEET_SNIPPETS_TAB || 'top_snippets'}!A1:Z`,
    writeSnippets: `${$env.GSHEET_SNIPPETS_TAB || 'top_snippets'}!A1:Z`,
    clearCreators: `${$env.GSHEET_CREATORS_TAB || 'creators'}!A1:Z`,
    writeCreators: `${$env.GSHEET_CREATORS_TAB || 'creators'}!A1:Z`
  };

  if (source.ok === false) {
    return [{
      json: {
        buildTag: BUILD_TAG,
        ok: false,
        dryRun: source.dryRun === true,
        reason: source.reason || 'AGGREGATION_ABORTED',
        message: source.message ? String(source.message) : null,
        warning: source.warning || null,
        startedAt: startedAtISO,
        finishedAt: finishedAtISO,
        durationMs,
        wouldWriteRanges: source.wouldWriteRanges || defaultWouldWriteRanges,
        summary: source.summary || {
          rawRowsRead: 0,
          windowRows: 0,
          uniqueVideos: 0,
          dailyRows: 0,
          keywordRows: 0,
          snippetRows: 0,
          rejectedCount: 0
        },
        creatorsRowsWritten: Number(source.creatorsRowsWritten || 0),
        creatorSummary: source.creatorSummary || {
          creatorsTotal: 0,
          rejectedCount: 0,
          previewCount: 0,
          groupingKey: 'authorProfileUrl_or_authorHandle'
        },
        creatorsPreviewTopN: source.creatorsPreviewTopN || [],
        creatorsRejectedWithReason: source.creatorsRejectedWithReason || [],
        dailyPreviewTop3: [],
        keywordPreviewTop3: [],
        snippetsPreviewTop3: []
      }
    }];
  }

  return [{
    json: {
      buildTag: BUILD_TAG,
      ok: true,
      dryRun: source.dryRun === true,
      workflow: 'KoreaSignals_Aggregator',
      days: source.days,
      windowStartKST: source.windowStartKST,
      windowEndKST: source.windowEndKST,
      startedAt: startedAtISO,
      finishedAt: finishedAtISO,
      durationMs,
      warning: source.warning || null,
      wouldWriteRanges: source.wouldWriteRanges || defaultWouldWriteRanges,
      summary: source.summary || {
        rawRowsRead: Number(source.totalRawRows || 0),
        windowRows: Number(source.filteredRows || 0),
        uniqueVideos: Number(source.dedupedRows || 0),
        dailyRows: 0,
        keywordRows: 0,
        snippetRows: 0,
        rejectedCount: Math.max(0, Number(source.totalRawRows || 0) - Number(source.filteredRows || 0))
      },
      creatorsRowsWritten: Number(source.creatorsRowsWritten || 0),
      creatorSummary: source.creatorSummary || {
        creatorsTotal: 0,
        rejectedCount: 0,
        previewCount: 0,
        groupingKey: 'authorProfileUrl_or_authorHandle'
      },
      creatorsPreviewTopN: source.creatorsPreviewTopN || [],
      creatorsRejectedWithReason: source.creatorsRejectedWithReason || [],
      sampleDedupedTop1: source.sampleDedupedTop1 || null,
      top5MappedRows: source.top5MappedRows || [],
      dailyPreviewTop3: source.dailyPreviewTop3 || [],
      keywordPreviewTop3: source.keywordPreviewTop3 || [],
      snippetsPreviewTop3: source.snippetsPreviewTop3 || []
    }
  }];
} catch (e) {
  const err = serializeError(e);
  return [{
    json: {
      buildTag: BUILD_TAG,
      ok: false,
      reason: 'FINALIZE_RESPONSE_ERROR',
      message: err?.message || 'Finalize response failed',
      error: err,
      dryRun: fallback.dryRun === true
    }
  }];
}

const source = $json || {};
const nowIso = new Date().toISOString();
const rows = Array.isArray(source.creatorsRowsFull) ? source.creatorsRowsFull : [];
const header = [
  'generatedAtISO',
  'authorHandle',
  'authorName',
  'authorNickName',
  'authorProfileUrl',
  'authorFollowers',
  'postsCount',
  'totalPlays',
  'avgPlays',
  'topPostUrl',
  'keywordsSeen'
];
const creatorsMatrix = [
  header,
  ...rows.map((r) => [
    nowIso,
    r.authorHandle ?? null,
    r.authorName ?? null,
    r.authorNickName ?? null,
    r.authorProfileUrl ?? null,
    r.authorFollowers ?? null,
    r.postsCount ?? null,
    r.totalPlays ?? null,
    r.avgPlays ?? null,
    r.topPostUrl ?? null,
    Array.isArray(r.keywordsSeen) ? r.keywordsSeen.join(', ') : (r.keywordsSeen ?? null)
  ])
];

return [{
  json: {
    ...source,
    creatorsRowsWritten: rows.length,
    creatorsMatrix
  }
}];
